@dataclass(slots=True)
class SuspiciousChunk:
    word_indices: list[int]  # indices of the suspicious words inside this chunk
    original_text: str       # original raw text of the suspicious span
    context_before: str
    context_after: str

    @property
    def context(self) -> str:
        return f"{self.context_before} [{self.original_text}] {self.context_after}".strip()

@runtime_checkable
class Storage(Protocol):
    """Minimal image storage interface used by the page/denoise pipeline."""

    def upload_image(self, data: bytes, *, folder: str, filename: str) -> StoredImage:
        """Persist raw image bytes and return its stored location."""
        ...

    def download(self, key_or_url: str) -> bytes:
        """Fetch raw bytes for a previously stored image (by key or URL)."""
        ...

    def delete(self, key: str) -> None:
        """Remove a stored image. Best-effort; missing objects are ignored."""
        ...

class LocalStorage:
    def upload_image(self, data: bytes, *, folder: str, filename: str) -> StoredImage:
        key = f"{folder}/{filename}" if folder else filename
        dest = _base_dir() / key
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(data)

        width = height = None
        try:
            with Image.open(io.BytesIO(data)) as img:
                width, height = img.width, img.height
        except Exception:  # noqa: BLE001
            logger.warning("Could not read dimensions for %s", key)

        logger.info("Stored image locally: %s", dest)
        return StoredImage(
            key=key,
            url=f"{_LOCAL_PREFIX}{key}",
            width=width,
            height=height,
            bytes_size=len(data),
        )

    def download(self, key_or_url: str) -> bytes:
        key = _key_from_reference(key_or_url)
        path = _base_dir() / key
        if not path.exists():
            raise FileNotFoundError(f"Local storage object not found: {key}")
        return path.read_bytes()

    def delete(self, key: str) -> None:
        path = _base_dir() / _key_from_reference(key)
        path.unlink(missing_ok=True)

}

export class ApiError extends Error {
  status: number
  detail: unknown

  constructor(status: number, message: string, detail?: unknown) {
    super(message)
    this.name = 'ApiError'
    this.status = status
    this.detail = detail
  }
}

